---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Kanban board: A sprint board where you and the agent move cards, with filters, details and keyboard moves.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change kanban-board.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './kanban-board.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="kanban" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="kbx">
  <div class="kbx-hd"><div class="kbx-ti"><b>Website refresh</b><span class="num"></span></div><div class="kbx-fp" role="group" aria-label="Filter by person"></div><span class="kbx-sp"></span><label class="kbx-q"><svg class="i xs"><use href="#i-search"/></svg><input type="search" placeholder="Search cards" aria-label="Search cards" autocomplete="off"><button class="ib kbx-qx" aria-label="Clear the search" hidden><svg class="i xs"><use href="#i-x"/></svg></button></label><div class="seg2 kbx-vw" role="group" aria-label="View"><button aria-pressed="true" data-v="board"><svg class="i xs"><use href="#i-grid"/></svg><span class="lb">Board</span></button><button aria-pressed="false" data-v="list"><svg class="i xs"><use href="#i-list"/></svg><span class="lb">List</span></button></div></div>
  <div class="kbx-fl"><button class="pill ghost sm kbx-clr" hidden>Clear</button><span class="kbx-sp"></span><span class="kbx-cnt num"></span></div>
  <div class="kbx-bd"><div class="kbx-cols"></div></div>
  <div class="kbx-sr" aria-live="polite"></div>
</div>
  </Fragment></div>
</div>
<script>
  import './kanban-board.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Kanban ---------- */
/* a sprint board: a header with the project, its people (a facepile that filters by person), a search and a Board / List
   switch; filter chips for assignee, label and priority; then the columns. The board never scrolls sideways: under 640px it
   shows one column at a time, picked with tabs, so the columns always fit */
.kbx{width:100%;position:relative;container:kbx/inline-size;display:flex;flex-direction:column;gap:10px}
.kbx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.kbx-sp{flex:1}
.kbx-hd{display:flex;align-items:center;gap:var(--dm-s-3);min-height:32px}
.kbx-ti{display:flex;align-items:baseline;gap:var(--dm-s-2);min-width:0}
.kbx-ti b{flex:none;font-size:14px;font-weight:500;white-space:nowrap}
/* the summary gives way first when the header is short of room */
.kbx-ti span{min-width:0;font-size:12.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* the people on the board: pressing a face shows only their cards, the same filter as the Assignee chip */
.kbx-fp{display:flex;flex:none;align-items:center;padding-left:5px}
.kbx-fp button{position:relative;display:grid;margin-left:-4px;border-radius:50%;transition:opacity .2s,filter .2s,transform .3s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.kbx-fp button:hover{transform:translateY(-1px)}}
.kbx-fp .av{width:24px;height:24px;font-size:10px;box-shadow:0 0 0 2px var(--dm-stage)}
.kbx-fp button[aria-pressed="true"] .av{box-shadow:0 0 0 2px var(--dm-stage),0 0 0 3.5px var(--dm-line-strong)}
.kbx-fp button[aria-pressed="true"]{z-index:1}
.kbx-fp.some button[aria-pressed="false"]{opacity:.45;filter:grayscale(1)}
.kbx-fp button:focus-visible{outline-offset:3px;border-radius:50%}
.kbx-q{display:flex;align-items:center;gap:6px;flex:0 1 176px;min-width:136px;height:30px;padding:0 var(--dm-s-1) 0 var(--dm-s-2);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);color:var(--dm-muted);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.kbx-q{border-radius:var(--dm-r-field-sq)}}
.kbx-q:focus-within{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.kbx-q input{flex:1;min-width:0;height:100%;border:0;outline:0;padding:0;background:none;font:inherit;font-size:13px;color:var(--dm-fg)}
.kbx-q input::placeholder{color:var(--dm-muted)}
.kbx-q input::-webkit-search-cancel-button{appearance:none}
.kbx-qx{width:22px;height:22px;flex:none;color:var(--dm-muted)}
.kbx-qx[hidden]{display:none}
.kbx-vw{flex:none}
.kbx-vw button{display:inline-flex;align-items:center;gap:5px}
.kbx-vw .i{color:var(--dm-muted)}
.kbx-vw button[aria-pressed="true"] .i{color:var(--dm-fg2)}
/* the filter chips: grey at rest, a white tile with the dimmed edge once they filter, saying what they filter by */
.kbx-fl{display:flex;align-items:center;flex-wrap:wrap;gap:6px;min-height:28px}
.kbx-f .v{color:var(--dm-fg);font-weight:500}
.kbx-f .i:last-child{color:var(--dm-muted);margin-right:-3px}
.kbx-f[aria-expanded="true"]{background:var(--dm-hover);color:var(--dm-fg)}
.kbx-f.on[aria-expanded="true"]{background:var(--dm-surface)}
.kbx-clr[hidden]{display:none}
.kbx-cnt{font-size:12.5px;color:var(--dm-muted);white-space:nowrap}
/* the columns, and the room they keep: each has space for four cards, the most one holds as the agent fills Done, so the
   board keeps one height while it plays, as you filter, and as a column folds away */
.kbx-bd{position:relative}
.kbx-cols{display:grid;grid-template-columns:var(--dm-kbx-gt,repeat(3,minmax(0,1fr)));gap:10px;transition:grid-template-columns var(--dm-t) var(--dm-ease)}
.kbx-c{display:flex;flex-direction:column;gap:6px;min-width:0;padding:6px 6px 8px;border-radius:var(--dm-r-card);background:color-mix(in srgb,var(--dm-fg) 3.5%,transparent);transition:background .25s,box-shadow .25s;min-height:452px}
.kbx-c.over{background:var(--dm-sel);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 40%,transparent)}
.kbx-ch{display:flex;align-items:center;gap:6px;height:30px;padding:0 0 0 2px;font-size:13px}
.kbx-ch b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kbx-ch .n{font-size:12px;color:var(--dm-muted);white-space:nowrap}
.kbx-ch .tag{height:20px;padding:0 6px;gap:3px;cursor:default}
.kbx-ch .ib{width:24px;height:24px;flex:none;color:var(--dm-muted)}
.kbx-ch .ib[aria-expanded="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.kbx-ch .ib:hover{color:var(--dm-fg)}}
.kbx-tg .i{transition:transform var(--dm-t) var(--dm-ease)}
.kbx-c.shut .kbx-tg .i{transform:rotate(-90deg)}
.kbx-list{display:flex;flex-direction:column;gap:6px;flex:1}
.kbx-none{padding:var(--dm-s-4) var(--dm-s-2);font-size:12px;color:var(--dm-muted);text-align:center}
/* a folded column is a narrow strip with its name running down it; pressing it opens it again, and a card dropped on it
   goes to its end */
.kbx-c.shut{align-items:center;padding:6px 0;cursor:pointer}
@media (hover:hover) and (pointer:fine){.kbx-c.shut:hover{background:color-mix(in srgb,var(--dm-fg) 5.5%,transparent)}}
.kbx-c.shut .kbx-ch{flex-direction:column;height:auto;padding:0;gap:var(--dm-s-2)}
.kbx-c.shut .kbx-ch b{writing-mode:vertical-rl}
.kbx-c.shut :is(.kbx-list,.kbx-sp,.kbx-cadd,.kbx-cmn,.kbx-none){display:none}
/* a card: its key, priority and people on top, the title, then its labels, due date, subtasks, comments and files */
.kbx-k{position:relative;padding:var(--dm-s-2) 10px 9px;border-radius:calc(12px * var(--dm-rk));background:var(--dm-raised);box-shadow:var(--dm-shadow);display:flex;flex-direction:column;gap:5px;cursor:grab;transition:box-shadow .25s,opacity .2s;touch-action:none;user-select:none;-webkit-user-select:none}
@media (hover:hover) and (pointer:fine){.kbx-k:hover{box-shadow:var(--dm-shadow-pop)}}
.kbx-k:focus-visible{outline-offset:1px;border-radius:calc(12px * var(--dm-rk))}
.kbx-k.drag{opacity:.35}
.kbx-k.ghost{position:fixed;z-index:100;pointer-events:none;transform:rotate(2deg) scale(1.03);box-shadow:var(--dm-shadow-pop);cursor:grabbing}
.kbx-k1{display:flex;align-items:center;gap:6px;height:20px}
.kbx-id{font-size:11.5px;color:var(--dm-muted);white-space:nowrap}
.kbx-k .t{font-size:13px;line-height:1.4;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
/* a title is written in place (a new card, or a double-click on one): while you write it, it is a field, white with the
   dimmed field edge, one step stronger while it has the focus, drawn outside the words so they keep their place */
.kbx-k .t[contenteditable="true"]{display:block;outline:0;border-radius:var(--dm-r-xs);padding:0 var(--dm-s-1);margin:0 calc(-1 * var(--dm-s-1));background:var(--dm-surface);box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);cursor:text;-webkit-user-select:text;user-select:text}
.kbx-k .t[contenteditable="true"]:focus{box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.kbx-m{display:flex;align-items:center;flex-wrap:wrap;gap:4px 10px;min-height:20px;font-size:12px;color:var(--dm-muted)}
.kbx-m:empty{display:none}
.kbx-tags{display:flex;gap:4px}
.kbx-mt{display:inline-flex;align-items:center;gap:3px;white-space:nowrap}
.kbx-mt .i{width:12px;height:12px}
.kbx-mt.late{color:var(--dm-bad)}
.kbx-mt.ok{color:var(--dm-ok)}
/* subtasks done: a count and a thin bar, grey while there is work left and green once it is all done */
.kbx-sb{width:22px;height:3px;border-radius:2px;background:color-mix(in srgb,var(--dm-muted) 25%,transparent);overflow:hidden}
.kbx-sb i{display:block;height:100%;border-radius:inherit;background:var(--dm-fg2);transition:width .35s var(--dm-ease)}
.kbx-mt.ok .kbx-sb i{background:var(--dm-ok-mark)}
/* the card's quick controls: its priority and its people open their menus, and the dots its Move to menu */
.kbx-pri,.kbx-who,.kbx-mv{display:inline-grid;place-items:center;flex:none;border-radius:calc(6px * var(--dm-rk));transition:background var(--dm-t-fast),color var(--dm-t-fast),opacity var(--dm-t-fast)}
.kbx-pri{width:20px;height:20px;margin:0 -2px 0 -4px}
.kbx-pri[aria-expanded="true"],.kbx-who[aria-expanded="true"],.kbx-mv[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.kbx-pri:hover,.kbx-who:hover,.kbx-mv:hover{background:var(--dm-row)}}
.kbx-who{display:inline-flex;align-items:center;height:22px;padding:0 1px 0 6px;border-radius:calc(11px * var(--dm-rk))}
.kbx-who .av{width:20px;height:20px;font-size:9px;margin-left:-5px;box-shadow:0 0 0 1.5px var(--dm-surface)}
.kbx-who:empty{width:22px;padding:0;box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);border-radius:50%}
.kbx-who .none{display:grid;place-items:center;width:20px;height:20px;margin-left:-5px;border-radius:50%;color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-muted) 45%,transparent)}
.kbx-mv{width:22px;height:22px;margin-right:-4px;color:var(--dm-muted);opacity:0}
.kbx-mv[aria-expanded="true"]{opacity:1}
@media (hover:hover) and (pointer:fine){.kbx-k:is(:hover,:focus-within,.open) .kbx-mv{opacity:1}}
.kbx-mv[aria-expanded="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.kbx-mv:hover{color:var(--dm-fg)}}
@media (pointer:coarse){.kbx-mv{opacity:1}}
/* priority, drawn as three bars that fill from the left; Urgent is the one in colour */
.kbx-pb{display:inline-flex;align-items:flex-end;gap:1.5px;width:12px;height:11px}
.kbx-pb i{flex:1;border-radius:1px;background:color-mix(in srgb,var(--dm-muted) 35%,transparent)}
.kbx-pb i:nth-child(1){height:45%}.kbx-pb i:nth-child(2){height:72%}.kbx-pb i:nth-child(3){height:100%}
.kbx-pb[data-p="low"] i:nth-child(1),.kbx-pb[data-p="med"] i:nth-child(-n+2),.kbx-pb[data-p="high"] i{background:var(--dm-fg2)}
.kbx-pb[data-p="none"] i{height:1.5px}
.kbx-pu{display:grid;place-items:center;width:12px;height:12px;border-radius:calc(3px * var(--dm-rk));background:var(--dm-bad);color:var(--dm-surface);font-size:10px;font-weight:500;line-height:1}
/* picked cards: a checkbox on each card while any is picked, and a slightly stronger edge on the picked ones */
.kbx-sel{display:none;place-items:center;width:14px;height:14px;flex:none;border-radius:calc(4px * var(--dm-rk));box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
.kbx.selecting .kbx-sel{display:grid}
.kbx-sel .i{width:10px;height:10px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.kbx-k.sel .kbx-sel{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.kbx-k.sel .kbx-sel .i{opacity:1;transform:none}
.kbx-k.sel,.kbx-k.open{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 70%,transparent),var(--dm-shadow)}
/* the agent's card: an accent edge, what it is doing now, and a bar that fills as it works */
.kbx-k.agent{box-shadow:0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent)),var(--dm-shadow)}
.kbx-ag{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-accent-fg,var(--dm-accent))}
.kbx-ag .think{color:var(--dm-accent-fg,var(--dm-accent))}
.kbx-ag .s{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.kbx-ag .pc{color:var(--dm-muted)}
.kbx-pr{height:3px;border-radius:2px;background:color-mix(in srgb,var(--dm-muted) 25%,transparent);overflow:hidden}
.kbx-pr i{display:block;height:100%;background:var(--dm-accent-mark,var(--dm-accent));width:0;transition:width .3s linear}
.kbx-ph{border-radius:calc(12px * var(--dm-rk));background:color-mix(in srgb,var(--dm-accent) 8%,transparent);border:1.5px dashed color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 50%,transparent)}
/* nothing matches the filters: one note over the board, with a way back */
.kbx-em{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;text-align:center;pointer-events:none}
.kbx-em[hidden]{display:none}
.kbx-em .ic{display:grid;place-items:center;width:36px;height:36px;margin-bottom:var(--dm-s-2);border-radius:var(--dm-r-in);background:var(--dm-chip);color:var(--dm-muted)}
.kbx-em b{font-size:13.5px;font-weight:500}
.kbx-em span{font-size:12.5px;color:var(--dm-muted)}
.kbx-em .pill{margin-top:10px;pointer-events:auto}
/* picked cards move together from a bar over the foot of the board */
.kbx-bk{position:absolute;left:50%;bottom:var(--dm-s-3);z-index:3;display:flex;align-items:center;gap:2px;max-width:calc(100% - 16px);padding:var(--dm-s-1) var(--dm-s-1) var(--dm-s-1) var(--dm-s-3);border-radius:calc(14px * var(--dm-rk));background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);font-size:12.5px;white-space:nowrap;transform:translate(-50%,8px);opacity:0;visibility:hidden;transition:opacity .2s var(--dm-ease),transform .35s var(--dm-ease),visibility 0s .2s}
.kbx-bk.on{transform:translate(-50%,0);opacity:1;visibility:visible;transition-property:opacity,transform}
.kbx-bk .n{font-weight:500;margin-right:var(--dm-s-2)}
.kbx-bk .l{color:var(--dm-muted);margin-right:2px}
.kbx-bk .sep{width:1px;height:18px;margin:0 var(--dm-s-1);background:color-mix(in srgb,var(--dm-line) 50%,transparent)}
.kbx-bk .ib{width:28px;height:28px}
.kbx-bk .sh{display:none}
/* a card's details, in a sheet over the right of the board: what it is, its fields (each opens its menu), the agent's
   progress, a checklist you can tick and how much talk and how many files it has */
.kbx-pk{position:absolute;top:0;right:0;bottom:0;z-index:4;width:min(300px,100%);display:flex;flex-direction:column;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-2) var(--dm-s-3) var(--dm-s-4);border-radius:var(--dm-r-card);background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);overflow:auto;overscroll-behavior:contain;opacity:0;visibility:hidden;transform:translateX(12px);transition:opacity .2s var(--dm-ease),transform .4s var(--dm-ease),visibility 0s .2s}
.kbx-pk.on{opacity:1;visibility:visible;transform:none;transition-property:opacity,transform}
.kbx-pk-h{display:flex;align-items:center;gap:var(--dm-s-2);min-height:30px}
.kbx-pk-h .ib{width:28px;height:28px}
.kbx-pk-t{font-size:14px;font-weight:500;line-height:1.4;padding-right:var(--dm-s-2)}
.kbx-pk-ag{display:flex;flex-direction:column;gap:6px;padding:var(--dm-s-2) 10px;margin-right:var(--dm-s-2);border-radius:var(--dm-r-in);background:var(--dm-accent-bg)}
.kbx-pk-ag .kbx-ag{color:var(--dm-accent-fg,var(--dm-accent))}
.kbx-pk-ag .pc{color:var(--dm-fg2)}
.kbx-pk-rows{display:flex;flex-direction:column}
.kbx-pk-r{display:grid;grid-template-columns:72px minmax(0,1fr);align-items:center;min-height:32px;font-size:13px}
.kbx-pk-r .k{color:var(--dm-muted)}
.kbx-pv{display:inline-flex;align-items:center;gap:7px;justify-self:start;max-width:100%;height:28px;padding:0 var(--dm-s-2);margin-left:calc(-1 * var(--dm-s-2));border-radius:var(--dm-r-sm);color:var(--dm-fg);white-space:nowrap;transition:background .2s}
:where([data-c]) button.kbx-pv[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){:where([data-c]) button.kbx-pv:hover{background:var(--dm-row)}}
.kbx-pv>.i{color:var(--dm-muted)}
.kbx-pv .av{width:20px;height:20px;font-size:9px}
.kbx-pv .avs{display:inline-flex}
.kbx-pv .avs .av+.av{margin-left:-5px;box-shadow:0 0 0 1.5px var(--dm-raised)}
.kbx-pv.late{color:var(--dm-bad)}
.kbx-pv .dot{width:8px;height:8px}
.kbx-pk .kbx-tags{flex-wrap:wrap}
.kbx-pk-s{display:flex;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) var(--dm-s-2) 2px 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
.kbx-pk-s b{font-weight:500;color:var(--dm-fg);font-size:13px}
.kbx-pk-s .kbx-sb{width:48px}
.kbx-pk-cl{display:flex;flex-direction:column;margin:0 0 0 -6px}
.kbx-ci{display:flex;align-items:flex-start;gap:var(--dm-s-2);width:100%;padding:5px 6px;border-radius:var(--dm-r-sm);font-size:13px;line-height:1.4;text-align:left;transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.kbx-ci:hover{background:var(--dm-row)}}
.kbx-ci:focus-visible{outline-offset:-2px}
.kbx-ci[aria-checked="true"]>span:last-child{color:var(--dm-muted);text-decoration:line-through;text-decoration-color:color-mix(in srgb,var(--dm-muted) 60%,transparent)}
.kbx-cb{display:grid;place-items:center;width:16px;height:16px;flex:none;margin-top:1px;border-radius:5px;box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));color:var(--dm-on-accent,#fff);transition:background-color .2s,box-shadow .2s}
.kbx-cb .i{width:11px;height:11px;opacity:0;transform:scale(.4);transition:opacity .15s,transform .3s cubic-bezier(.34,1.4,.64,1)}
.kbx-ci[aria-checked="true"] .kbx-cb{background:var(--dm-accent);box-shadow:inset 0 0 0 1px var(--dm-accent-mark,var(--dm-accent))}
.kbx-ci[aria-checked="true"] .kbx-cb .i{opacity:1;transform:none}
.kbx-ci:disabled{cursor:default}
@media (hover:hover) and (pointer:fine){.kbx-ci:disabled:hover{background:none}}
.kbx-pk-f{display:flex;gap:var(--dm-s-3);padding-top:var(--dm-s-2);margin-top:auto;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12px;color:var(--dm-muted)}
.kbx-pk-f .kbx-mt .i{width:13px;height:13px}
/* the menus: Move to, a card's priority and people, a column's actions and the filters */
.kbx-mp,.kbx-pm{min-width:184px}
.kbx-am,.kbx-fm{min-width:208px}
.kbx-cm{min-width:196px}
.kbx-pop .mi .av{width:20px;height:20px;font-size:9px}
.kbx-pop .mi .r{margin-left:auto}
.kbx-pop .mi .r+.ck{margin-left:0}
.kbx-pop .mi>.kbx-pb,.kbx-pop .mi>.kbx-pu{margin:0 4px 0 3px}
.kbx-pop .mi .tag{height:18px;padding:0 6px}
/* the list: the same cards as rows, grouped by column under a header each, in one panel that keeps the board's height */
.kbx.list .kbx-cols{display:flex;flex-direction:column;gap:0;border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);overflow:hidden}
.kbx.list .kbx-c{min-height:0;padding:0;gap:0;border-radius:0;background:none;cursor:default}
.kbx.list .kbx-c.over{background:var(--dm-sel);box-shadow:none}
.kbx.list .kbx-ch{height:32px;padding:0 var(--dm-s-2) 0 6px;background:var(--dm-row);box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent)}
.kbx.list .kbx-c+.kbx-c .kbx-ch{box-shadow:inset 0 1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent),inset 0 -1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent)}
.kbx.list .kbx-c.shut{align-items:stretch}
.kbx.list .kbx-c.shut .kbx-ch{flex-direction:row;height:32px;padding:0 var(--dm-s-2) 0 6px;gap:6px}
.kbx.list .kbx-c.shut .kbx-ch b{writing-mode:horizontal-tb}
.kbx.list .kbx-c.shut .kbx-sp{display:block}
.kbx.list .kbx-list{gap:0}
.kbx.list .kbx-k{flex-direction:row;align-items:center;gap:10px;height:38px;padding:0 var(--dm-s-3) 0 var(--dm-s-3);border-radius:0;box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent)}
.kbx.list .kbx-k:last-child{box-shadow:none}
@media (hover:hover) and (pointer:fine){.kbx.list .kbx-k:hover{box-shadow:inset 0 -1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent);background:var(--dm-row)}}
.kbx.list .kbx-k.sel,.kbx.list .kbx-k.open{background:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.kbx.list .kbx-k.agent{box-shadow:inset 2px 0 0 var(--dm-accent-mark,var(--dm-accent)),inset 0 -1px 0 color-mix(in srgb,var(--dm-line) 50%,transparent)}
.kbx.list .kbx-k:focus-visible{outline-offset:-2px;border-radius:0}
.kbx.list .kbx-k.ghost{border-radius:calc(10px * var(--dm-rk));box-shadow:var(--dm-shadow-pop)}
.kbx.list .kbx-k1{display:contents}
.kbx.list .kbx-sel{order:0}.kbx.list .kbx-pri{order:1}.kbx.list .kbx-id{order:2;width:52px}
.kbx.list .kbx-k .t{order:3;flex:1;min-width:0;display:block;white-space:nowrap;text-overflow:ellipsis}
.kbx.list .kbx-ag{order:4;flex:none}.kbx.list .kbx-ag .s{display:none}
.kbx.list .kbx-pr{order:5;width:40px;flex:none}
.kbx.list .kbx-m{order:6;flex-wrap:nowrap}
.kbx.list .kbx-k1 .kbx-sp{display:none}
.kbx.list .kbx-who{order:7}.kbx.list .kbx-mv{order:8}
.kbx.list .kbx-none{padding:10px var(--dm-s-3);text-align:left}
.kbx.list .kbx-ph{border-radius:0;border-width:1.5px 0}
/* a narrow board, on a phone or in a narrow card: the header stacks, one column at a time, picked with tabs that count each
   column's cards, and the details sheet covers the board */
.kbx-bar{display:none}
@container kbx (max-width:639px){
  .kbx-hd{flex-wrap:wrap;row-gap:var(--dm-s-2)}
  .kbx-hd .kbx-sp{display:none}
  .kbx-ti{flex:1 0 auto}
  .kbx-ti span{display:none}
  .kbx-q{order:3;flex:1 1 180px;min-width:0;width:auto}
  .kbx-vw{order:4}
  .kbx-vw .lb{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
  .kbx-vw button{padding:0 9px}
  .kbx-cnt{display:none}
  .kbx:not(.list) .kbx-bar{display:flex;align-items:center;gap:var(--dm-s-2)}
  .kbx-tabs{flex:1;display:flex;min-width:0}
  .kbx-tabs button{flex:1;display:inline-flex;align-items:center;justify-content:center;gap:6px;min-width:0;padding:0 var(--dm-s-2);white-space:nowrap}
  .kbx-tabs .n{font-size:12px;color:var(--dm-muted)}
  .kbx-add{flex:none;width:30px;height:30px;color:var(--dm-muted)}
  @media (hover:hover) and (pointer:fine){.kbx-add:hover{color:var(--dm-fg)}}
  .kbx:not(.list) .kbx-cols{grid-template-columns:minmax(0,1fr)}
  .kbx:not(.list) .kbx-c:not(.on){display:none}
  .kbx:not(.list) .kbx-ch{display:none}
  .kbx:not(.list) .kbx-c.shut{align-items:stretch;padding:6px 6px 8px;cursor:default}
  .kbx:not(.list) .kbx-c.shut .kbx-list{display:flex}
  .kbx:not(.list) .kbx-c{min-height:412px}
  .kbx-k{touch-action:pan-y}
  .kbx-mv{opacity:1}
  .kbx.list .kbx-id,.kbx.list .kbx-m,.kbx.list .kbx-pr{display:none}
  .kbx-pk{width:100%}
  .kbx-bk{left:var(--dm-s-2);right:var(--dm-s-2);max-width:none;transform:translateY(8px)}
  .kbx-bk.on{transform:none}
  .kbx-bk .lg{display:none}
  .kbx-bk .sh{display:inline}
  .kbx-bk .l{display:none}
  .kbx-bk .n{margin-right:auto}
}

